/* eslint-disable */
/* global WebImporter */

/**
 * Parser for the base `form` block (forms are never variants).
 * Sources:
 *  - Beckman: the Marketo form (form.mktoForm / form#mktoForm_*) on beckmancoulter.com
 *    solution pages. Marketo renders its fields client-side, so the field
 *    definitions are not read here: they live in the EDS form JSON generated by the
 *    forms migration (form-importer.js), served with the site code under /forms/.
 *  - GSPANN: the non-Marketo email "Get Started" subscribe form in section #approach
 *    (www.gspann.com service pages) → /forms/gspann-get-started.json.
 *
 * Output: 2-row block — "Form" | link to the form JSON. xwalk model `form-file`
 * (blocks/form/_form-file.json): single aem-content field `reference`.
 */

const FORM_JSON = {
  '2549': '/forms/speak-to-representative.json',
};
const DEFAULT_FORM_JSON = '/forms/speak-to-representative.json';
const GSPANN_FORM_JSON = '/forms/gspann-get-started.json';

function isMarketo(element) {
  return element.classList.contains('mktoForm')
    || /^mktoForm_/.test(element.id || '')
    || !!element.querySelector('input[name="formid"], input[name="munchkinId"]');
}

function isGspann(element, document) {
  if (element.closest('#approach')) return true;
  const hints = [
    document.querySelector('link[rel="canonical"]')?.getAttribute('href'),
    document.querySelector('meta[property="og:url"]')?.getAttribute('content'),
  ];
  try { hints.push(document.location?.href); } catch (e) { /* no location in some DOMs */ }
  return hints.some((h) => /(^|\/\/|\.)gspann\.com/i.test(h || ''));
}

export default function parse(element, { document }) {
  // Marketo appends an empty, hidden helper <form>; only the real form becomes a block
  const visibleFields = element.querySelectorAll('input:not([type="hidden"]), select, textarea');
  if (!visibleFields.length) {
    element.remove();
    return;
  }

  let file;
  if (isMarketo(element)) {
    const formId = (element.id || '').replace(/^mktoForm_/, '')
      || (element.querySelector('input[name="formid"]')?.getAttribute('value') || '');
    file = FORM_JSON[formId] || DEFAULT_FORM_JSON;
  } else if (isGspann(element, document)) {
    file = GSPANN_FORM_JSON;
  } else {
    file = DEFAULT_FORM_JSON;
  }

  const link = document.createElement('a');
  link.href = file;
  link.textContent = file;

  const block = WebImporter.Blocks.createBlock(document, {
    name: 'Form',
    cells: [[[document.createComment(' field:reference '), link]]],
  });
  element.replaceWith(block);
}
